import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>50KB, 100KB না 200KB — কোন আকারটি বেছে নেবেন? ফরমের সীমা, ওয়েবসাইটের গতি আর ছবির মান — তিনটি বিষয়ই এই সিদ্ধান্তের উপর নির্ভর করে।</p>\n<p>তিনটি আকারের মধ্যে পার্থক্য শুধু সংখ্যায় নয়। প্রতিটি আকারে ছবি দেখতে কেমন লাগে, কোথায় ব্যবহার করা যায়, আর কত দ্রুত লোড হয় — সবই আলাদা।</p>\n<p>এই তুলনায় আপনি একই ছবিকে তিনটি আকারে দেখবেন, প্রতিটির সুবিধা-অসুবিধা জানবেন, আর এক মিনিটে সিদ্ধান্ত নেওয়ার একটি সহজ নিয়ম পাবেন।</p>\n<h2 id=\"the-short-answer\">সংক্ষিপ্ত উত্তর</h2>\n<p>পোর্টাল সীমা দিলে সেটাই মেনে চলুন। সীমা না থাকলে সাধারণ ব্যবহারের জন্য 100KB ভালো ভারসাম্য দেয়।</p>\n<p>ব্লগ, দোকান আর বড় ছবির জন্য 200KB বেছে নিন। এতে ছবি মূলের প্রায় কাছাকাছি দেখায়।</p>\n<p>শুধু কঠোর ফরমের জন্যই 50KB ব্যবহার করুন। এটি কাজ চালায়, কিন্তু মানের সঙ্গে আপস করতে হয়।</p>\n<h2 id=\"what-50kb-looks-like\">50KB ছবি দেখতে কেমন লাগে</h2>\n<p>50KB-তে মুখ চেনা যায়, লেখা পড়া যায়, কিন্তু সূক্ষ্ম বিবরণ নরম হয়ে যায়। চুলের গোছা আর কাপড়ের বুনন অস্পষ্ট লাগে।</p>\n<p>ছোট আকারে দেখালে, যেমন পাসপোর্ট ছবি বা অ্যাভাটারে, এই নরমভাব প্রায় চোখে পড়ে না।</p>\n<p>বড় করে দেখালে পার্থক্য স্পষ্ট হয়। তাই 50KB বড় ছবি দেখানোর জন্য নয়, ফরম পূরণের জন্য।</p>\n<h2 id=\"what-100kb-looks-like\">100KB ছবি দেখতে কেমন লাগে</h2>\n<p>100KB-তে প্রতিকৃতি অনেক পরিষ্কার দেখায়। চোখের পাতা, চশমার ফ্রেম আর চুলের প্রান্ত 50KB-এর চেয়ে স্পষ্ট থাকে।</p>\n<p>ব্লগের থাম্বনেইল আর প্রোফাইল ছবির জন্য 100KB যথেষ্ট। বেশিরভাগ মানুষ মূল ছবির সঙ্গে পার্থক্য ধরতে পারে না।</p>\n<p>লেখা থাকা স্ক্রিনশটও 100KB-তে ভালো থাকে। ছোট অক্ষর পড়া যায়, যদিও খুব ছোট লেখা একটু নরম হতে পারে।</p>\n<h2 id=\"what-200kb-looks-like\">200KB ছবি দেখতে কেমন লাগে</h2>\n<p>200KB-তে বেশিরভাগ ছবি মূলের মতোই দেখায়। সাধারণ মনিটরে পাশাপাশি রাখলেও পার্থক্য খুঁজে পাওয়া কঠিন।</p>\n<p>পণ্যের ছবি, প্রাকৃতিক দৃশ্য আর বিস্তারিত গ্রাফিক্সের জন্য 200KB ভালো পছন্দ। রং আর টেক্সচার প্রায় পুরোপুরি থাকে।</p>\n<p>ওয়েবসাইটের হিরো ছবি আর গ্যালারির জন্য এই আকারটি প্রায়ই মান আর গতির সেরা ভারসাম্য দেয়।</p>\n<p>২০০KB ছবিতে চোখের পাতা, চুলের রেখা আর জামার ভাঁজ স্পষ্ট দেখা যায়। পাসপোর্ট ছবিতে এই পরিষ্কারভাব গুরুত্বপূর্ণ, কারণ কর্মকর্তারা মুখের সঙ্গে ছবি মিলিয়ে দেখেন। অস্পষ্ট ছবি সন্দেহ তৈরি করতে পারে।</p>\n<p>২০০KB-তে একটি ল্যান্ডস্কেপ ছবির আকাশ মসৃণ থাকে, আর গাছপালার সবুজে রঙের স্তর দেখা যায়। ৫০KB-তে একই ছবিতে রঙের দাগ বা ব্যান্ডিং চোখে পড়তে পারে। পার্থক্যটি ফোনের স্ক্রিনেও ধরা পড়ে।</p>\n<p>ব্লগের হিরো ছবি হিসেবে ২০০KB ভালো কাজ করে। পাতা লোড হতে একটু বেশি সময় লাগলেও পাঠক প্রথমেই একটি পরিষ্কার ছবি দেখেন। লেখার মানের সঙ্গে ছবির মান মিলে যায়।</p>\n<p>২০০KB ছবি ইমেইলে পাঠানো সহজ। বেশিরভাগ ইমেইল সেবা ২৫MB পর্যন্ত সংযুক্তি নেয়, তাই কয়েকটি ২০০KB ছবি একসঙ্গে পাঠালেও সমস্যা হয় না। প্রাপক দ্রুত ডাউনলোড করতে পারেন।</p>\n<p>অনলাইন দোকানে ২০০KB পণ্যের ছবি ক্রেতার আস্থা বাড়ায়। সেলাই, বোতাম বা কাপড়ের বুনন স্পষ্ট দেখা গেলে ক্রেতা পণ্যটি ভালোভাবে বুঝতে পারেন। অস্পষ্ট ছবি বিক্রি কমিয়ে দেয়।</p>\n<p>২০০KB-তে স্ক্যান করা নথির ছোট লেখা পড়া যায়। সার্টিফিকেটের নাম, তারিখ আর সিলের লেখা পরিষ্কার থাকে। ৫০KB-তে একই লেখা ভেঙে যেতে পারে।</p>\n<p>২০০KB ছবি ছাপালে ছোট আকারে ভালো ফল পাওয়া যায়। চার ইঞ্চি বাই ছয় ইঞ্চি ছাপায় ছবি পরিষ্কার থাকে। বড় পোস্টার ছাপার জন্য অবশ্য আরও বড় ফাইল দরকার।</p>\n<p>সোশ্যাল মিডিয়ায় ২০০KB ছবি আপলোড করলে প্ল্যাটফর্ম নিজে থেকে খুব বেশি কমপ্রেস করে না। ফলে আপনার ছবি যেমন তুলেছেন তেমনই দেখায়। ৫০KB ছবি আপলোড করলে প্ল্যাটফর্মের কমপ্রেশন আরও ক্ষতি করতে পারে।</p>\n<p>২০০KB বেছে নেওয়ার আগে পোর্টালের নিয়ম দেখুন। কিছু পোর্টাল সর্বোচ্চ ১০০KB চায়, সেখানে ২০০KB ফাইল ফিরে আসবে। নিয়ম না থাকলে ২০০KB একটি নিরাপদ ও পরিষ্কার পছন্দ।</p>\n<h2 id=\"side-by-side\">পাশাপাশি: একই ছবি তিন আকারে</h2>\n<p>একই প্রতিকৃতিকে তিনটি আকারে কমপ্রেস করে দেখুন। 50KB-তে মুখ ঠিক থাকে, কিন্তু পেছনের গাছপালা মিলিয়ে যায়।</p>\n<p>100KB-তে পেছনের বিবরণ ফিরে আসতে শুরু করে। গাছের পাতা আর কাপড়ের ভাঁজ আলাদা করা যায়।</p>\n<p>200KB-তে ছবিটি প্রায় মূলের মতো। তিনটি পাশাপাশি দেখলে কোন আকার কোথায় যথেষ্ট, তা নিজেই বুঝতে পারবেন।</p>\n<h2 id=\"file-size-and-dimensions\">ফাইলের আকারই সব নয়</h2>\n<p>একই 100KB ফাইল 800 পিক্সেল চওড়া ছবিতে পরিষ্কার দেখায়, কিন্তু 3000 পিক্সেল চওড়া ছবিতে ঝাপসা লাগে। কারণ বাজেটটি বেশি পিক্সেলে ভাগ হয়ে যায়।</p>\n<p>তাই আকার বেছে নেওয়ার সময় মাপও ভাবুন। ছোট মাপের ছবি কম বাজেটেও ভালো দেখায়।</p>\n<p>ওয়েবসাইটে ছবি যে আকারে দেখানো হবে, সেই মাপে রাখাই বুদ্ধিমানের কাজ। বড় মাপ রেখে বেশি কমপ্রেস করার চেয়ে ছোট মাপে কম কমপ্রেস করা ভালো।</p>\n<h2 id=\"which-size-for-which-job\">কোন কাজে কোন আকার</h2>\n<p>পাসপোর্ট, ভিসা আর পরীক্ষার ফরমে 50KB ব্যবহার করুন। এসব জায়গায় সীমাই নিয়ম।</p>\n<p>সিভি, প্রোফাইল ছবি আর ব্লগ থাম্বনেইলে 100KB ব্যবহার করুন। মান ভালো থাকে আর ফাইলও হালকা থাকে।</p>\n<p>পণ্যের ছবি, গ্যালারি আর হিরো ছবিতে 200KB ব্যবহার করুন। এখানে মানই প্রধান বিষয়।</p>\n<p>কাজ অনুযায়ী আকার বেছে নিন, অভ্যাস অনুযায়ী নয়। পোর্টালের ফরমে ৫০KB, ব্লগের থাম্বনেইলে ১০০KB, আর দোকানের পণ্যের ছবিতে ২০০KB ভালো। কাজ না জেনে আকার বেছে নিলে ভুল হয়।</p>\n<p>আকার বেছে নেওয়ার আগে পাঠকের ডিভাইস ভাবুন। মোবাইলে দেখা ছবিতে ১০০KB যথেষ্ট। বড় মনিটরে দেখা ছবিতে ২০০KB ভালো। দর্শক ফোনে দেখলে বড় ফাইল অযথা।</p>\n<p>আকার বেছে নেওয়ার সময় ইন্টারনেটের গতি ভাবুন। ধীর ইন্টারনেটের দেশে ছোট ফাইল ভালো। দ্রুত ইন্টারনেটের জায়গায় বড় ফাইলও চলে। দর্শক কোথায় থাকেন তা জানুন।</p>\n<p>আকার বেছে নেওয়ার সময় ছবির সংখ্যা ভাবুন। একটি পাতায় দশটি ছবি থাকলে প্রতিটি ১০০KB রাখুন। মোট ওজন ১MB হয়। প্রতিটি ২০০KB রাখলে মোট ২MB হয়।</p>\n<p>আকার বেছে নেওয়ার সময় ছবির গুরুত্ব ভাবুন। হিরো ছবিতে ২০০KB দিন, আর ছোট আইকনে ৫০KB দিন। গুরুত্বপূর্ণ ছবিতে বেশি আকার দেওয়া যুক্তিসংগত।</p>\n<p>আকার বেছে নেওয়ার সময় ভবিষ্যতের ব্যবহার ভাবুন। ছবিটি পরে ছাপানোর পরিকল্পনা থাকলে ২০০KB রাখুন। শুধু ওয়েবে দেখানোর জন্য ১০০KB যথেষ্ট।</p>\n<p>আকার বেছে নেওয়ার সময় সার্চ ইঞ্জিনের কথা ভাবুন। গুগল দ্রুত পাতাকে ভালো র‍্যাঙ্ক দেয়। ছোট ছবির পাতা দ্রুত লোড হয়। র‍্যাঙ্কের জন্য ছোট আকার ভালো।</p>\n<p>আকার বেছে নেওয়ার সময় পরীক্ষা করুন। একই ছবি তিনটি আকারে তৈরি করে দেখুন। কোন আকারে ছবি পরিষ্কার লাগে তা চোখে দেখে বুঝুন।</p>\n<p>আকারের সিদ্ধান্ত লিখে রাখুন। দলের সবাই একই নিয়মে আকার বেছে নিলে ওয়েবসাইটের ছবি একরকম থাকে। নিয়মটি একটি নথিতে লিখে রাখুন।</p>\n<h2 id=\"format-effects\">ফরম্যাট কীভাবে তুলনা বদলে দেয়</h2>\n<p>JPG ছবির ক্ষেত্রে তিনটি আকারেই ভালো কাজ করে। ত্বকের রং আর গ্রেডিয়েন্ট এতে মসৃণ থাকে।</p>\n<p>WebP একই আকারে JPG-এর চেয়ে সামান্য বেশি বিবরণ ধরে রাখে। আধুনিক ব্রাউজার আর নতুন পোর্টালে এটি ভালো পছন্দ।</p>\n<p>PNG ছবির ক্ষেত্রে তিনটি আকারেই পিছিয়ে থাকে। 200KB-তেও বিস্তারিত PNG ছবি বড় থেকে যেতে পারে।</p>\n<h2 id=\"loading-speed\">পাতা লোডের গতি কেমন হবে?</h2>\n<p>একটি ছবিতে পার্থক্য ছোট মনে হতে পারে, কিন্তু দশটি ছবির পাতায় 50KB আর 200KB-এর পার্থক্য দেড় মেগাবাইটের বেশি হয়।</p>\n<p>ধীর মোবাইল সংযোগে এই পার্থক্য কয়েক সেকেন্ডের। ব্যবহারকারী অপেক্ষা না করে পাতা ছেড়ে দিতে পারে।</p>\n<p>তাই ওয়েবসাইটে সবচেয়ে বড় আকারটি বেছে নেওয়ার আগে ভাবুন, ছবিটি কত বড় দেখানো হবে। ছোট দেখালে ছোট আকারই যথেষ্ট।</p>\n<h2 id=\"decision-framework\">এক মিনিটে সিদ্ধান্ত নেওয়ার নিয়ম</h2>\n<p>প্রথমে জিজ্ঞেস করুন, কোনো সীমা আছে কি না। থাকলে সেই সীমাই আপনার উত্তর।</p>\n<p>সীমা না থাকলে জিজ্ঞেস করুন, ছবিটি কত বড় দেখানো হবে। ছোট দেখালে 100KB, বড় দেখালে 200KB নিন।</p>\n<p>সবশেষে ফরম্যাট দেখুন। ছবির জন্য JPG বা WebP, লেখা বা লোগোর জন্য PNG বেছে নিন।</p>\n<h2 id=\"when-to-use-100kb-instead\">কখন 50KB থেকে 100KB-তে যাবেন</h2>\n<p>পোর্টাল 100KB নিলে 50KB-তে চাপার কোনো মানে নেই। বাড়তি 50KB ছবিকে অনেক পরিষ্কার করে।</p>\n<p>ছবিতে ছোট লেখা থাকলে 100KB বেছে নিন। 50KB-তে সেই লেখা পড়া কঠিন হতে পারে।</p>\n<p>ছবিটি বারবার ব্যবহার হবে, যেমন সিভির ছবি, তাহলে 100KB রাখুন। একবার ভালো করে বানালে বারবার কাজে লাগবে।</p>\n<h2 id=\"quality-vs-dimensions\">কোয়ালিটি বনাম মাপ: আসল হিসাব</h2>\n<p>অনেকেই শুধু কোয়ালিটি স্লাইডার দেখেন, কিন্তু মাপও সমান গুরুত্বপূর্ণ। বড় মাপে একই কোয়ালিটি বেশি ডেটা চায়।</p>\n<p>100KB বাজেটে 2000 পিক্সেলের ছবি নরম দেখাতে পারে, কিন্তু 1000 পিক্সেলের ছবি পরিষ্কার দেখায়।</p>\n<p>তাই লক্ষ্য না মিললে প্রথমে মাপ একটু কমান। এতে কোয়ালিটি বেশি রাখা যায় আর ফলও ভালো হয়।</p>\n<h2 id=\"colour-banding\">রঙের ব্যান্ডিং কীভাবে দেখা দেয়</h2>\n<p>আকাশ বা দেয়ালের মতো মসৃণ গ্রেডিয়েন্টে কমপ্রেশন ব্যান্ড তৈরি করতে পারে। আকাশে ধাপ ধাপ রঙের দাগ দেখা যায়।</p>\n<p>50KB-তে ব্যান্ডিং সবচেয়ে বেশি দেখা যায়, কারণ বাজেট খুব কম। 100KB-তে তা অনেক কমে যায়।</p>\n<p>ব্যান্ডিং কমাতে WebP ব্যবহার করুন বা মাপ একটু কমান। দুটোই গ্রেডিয়েন্টকে মসৃণ রাখতে সাহায্য করে।</p>\n<p>মানের সঙ্গে মাপের সম্পর্ক আছে। বড় মাপের ছবি ছোট ফাইলে রাখলে মান কমে। ছোট মাপের ছবি ছোট ফাইলে রাখলে মান ঠিক থাকে। মাপ আর মানের ভারসাম্য রাখুন।</p>\n<p>মানের সঙ্গে মাপের ভারসাম্য পরীক্ষা করে দেখুন। একই ছবি দুটি মাপে তৈরি করে তুলনা করুন। কোন মাপে ছবি পরিষ্কার লাগে তা চোখে দেখে বুঝুন।</p>\n<p>মাপ কমালে ফাইল ছোট হয়, তবে ছবি ছোট দেখায়। ওয়েবসাইটে ছোট ছবি ঠিক আছে। ছাপায় ছোট ছবি ঝাপসা হয়। ব্যবহার অনুযায়ী মাপ বেছে নিন।</p>\n<p>মান বাড়াতে মাপ বাড়ানো যায় না। ছোট ছবি বড় করলে মান বাড়ে না, শুধু ঝাপসা হয়। মান বাড়াতে মূল বড় ছবি দরকার।</p>\n<p>মাপ আর মানের সিদ্ধান্ত নেওয়ার সময় স্ক্রিনের আকার দেখুন। মোবাইলে ছোট মাপ যথেষ্ট। বড় মনিটরে বড় মাপ দরকার। দর্শকের স্ক্রিন জানুন।</p>\n<p>মাপ আর মানের ভারসাম্য রাখতে WebP ব্যবহার করুন। WebP ছোট মাপেও ভালো মান দেয়। JPG-এর চেয়ে WebP-তে মাপ কমানো সহজ।</p>\n<p>মাপ আর মানের সিদ্ধান্ত লিখে রাখুন। দলের সবাই একই মাপ আর মান ব্যবহার করলে ছবি একরকম থাকে। নিয়মটি নথিতে লিখুন।</p>\n<p>মাপ কমানোর আগে ছবি ক্রপ করুন। ক্রপ করলে অপ্রয়োজনীয় অংশ বাদ যায়। ক্রপ করা ছবি ছোট মাপেও পরিষ্কার থাকে।</p>\n<p>মাপ আর মানের ভারসাম্য রাখতে প্রিভিউ দেখুন। প্রিভিউতে ছবি কেমন দেখায় তা দেখা যায়। ছবি ঝাপসা লাগলে মাপ বাড়ান।</p>\n<h2 id=\"choosing-between-the-three\">তিনটির মধ্যে বেছে নেওয়া</h2>\n<p>তিনটি আকারই একই টুল দিয়ে বানানো যায়। একবার মূল ছবি দিয়ে তিনটি সংস্করণ বানিয়ে পাশাপাশি দেখুন।</p>\n<p>যে আকারে ছবিটি আপনার কাজের জন্য যথেষ্ট পরিষ্কার, সেটাই নিন। তার চেয়ে বড় আকারের দরকার নেই।</p>\n<p>অনিশ্চিত হলে মাঝেরটি নিন। 100KB বেশিরভাগ কাজে নিরাপদ পছন্দ।</p>\n<h2 id=\"future-proofing\">ভবিষ্যতের জন্য কোনটি রাখবেন</h2>\n<p>মূল ছবি সবসময় আলাদাভাবে সংরক্ষণ করুন। আজকের 50KB ফাইল ভবিষ্যতের বড় পর্দায় ভালো দেখাবে না।</p>\n<p>কমপ্রেস করা ফাইল শুধু সেই কাজের জন্যই রাখুন যার জন্য বানানো হয়েছে। নতুন কাজে মূল ছবি থেকে আবার বানান।</p>\n<p>ক্লাউডে মূল ছবি রাখলে নাম পরিষ্কার রাখুন। বছরখানেক পরেও যেন বুঝতে পারেন কোনটি মূল ফাইল।</p>\n<p>ভবিষ্যতে ছবির আকারের মানদণ্ড বদলাতে পারে। আজকের ২০০KB পরে ছোট মনে হতে পারে। মূল ফাইল থাকলে নতুন মানদণ্ডে তৈরি করা যায়।</p>\n<p>ভবিষ্যতে ইন্টারনেট আরও দ্রুত হবে। দ্রুত ইন্টারনেটে বড় ফাইলও চলে। তবে মোবাইল ডেটার খরচ এখনও গুরুত্বপূর্ণ। ছোট ফাইল সবসময় ভালো।</p>\n<p>ভবিষ্যতে নতুন ফরম্যাট আসতে পারে। AVIF এখন আসছে। AVIF WebP-এর চেয়েও ছোট ফাইল দেয়। নতুন ফরম্যাটের দিকে নজর রাখুন।</p>\n<p>ভবিষ্যতে স্ক্রিনের রেজোলিউশন বাড়বে। বড় স্ক্রিনে ছোট ছবি ঝাপসা দেখায়। মূল বড় ছবি সংরক্ষণ করুন।</p>\n<p>ভবিষ্যতে সার্চ ইঞ্জিনের নিয়ম বদলাতে পারে। গতি এখনও গুরুত্বপূর্ণ থাকবে। ছোট ছবির পাতা সবসময় ভালো র‍্যাঙ্ক পাবে।</p>\n<p>ভবিষ্যতে ছবির ব্যবহার বদলাতে পারে। আজকের ব্লগের ছবি পরে ভিডিওর থাম্বনেইল হতে পারে। মূল ফাইল থাকলে যেকোনো ব্যবহারে তৈরি করা যায়।</p>\n<p>ভবিষ্যতে স্টোরেজ সস্তা হবে। তবে হাজারটি ছবির স্টোরেজ এখনও খরচের বিষয়। ছোট ফাইল স্টোরেজ বাঁচায়।</p>\n<p>ভবিষ্যতে ছবি সম্পাদনার টুল আরও ভালো হবে। নতুন টুলে পুরোনো ছবি আরও ভালো করা যাবে। মূল ফাইল থাকলে নতুন টুলে কাজ করা যায়।</p>\n<p>ভবিষ্যতের কথা ভেবে মূল ফাইল সংরক্ষণ করুন। মূল ফাইল একটি বিনিয়োগ। একদিন এটি কাজে লাগবে।</p>\n<h2 id=\"upload-speeds\">আপলোডের গতিতেও পার্থক্য আছে</h2>\n<p>ধীর সংযোগে 200KB ফাইল আপলোড করতে 50KB ফাইলের চেয়ে চার গুণ সময় লাগে। ফরম পূরণের সময় এটি বিরক্তিকর হতে পারে।</p>\n<p>মোবাইল ডেটায় একাধিক ছবি আপলোড করলে ছোট আকার অনেক সময় বাঁচায়।</p>\n<p>তাই ফরমের ক্ষেত্রে সবচেয়ে ছোট গ্রহণযোগ্য আকারটি বেছে নেওয়াই বুদ্ধিমানের কাজ।</p>\n<h2 id=\"printing-50kb\">50KB ছবি কি ছাপানো যায়?</h2>\n<p>ছোট আকারে ছাপালে 50KB ছবি চলতে পারে, যেমন পরিচয়পত্রের ছোট ছবি। তবে বড় ছাপায় এটি ঝাপসা দেখাবে।</p>\n<p>ছাপার জন্য 200KB বা তার বেশি ভালো। কাগজে ছবি বড় দেখায়, তাই বেশি বিবরণ দরকার হয়।</p>\n<p>ছাপার কাজে মূল ছবিই সবচেয়ে ভালো। কমপ্রেস করা ফাইল শুধু তখনই ব্যবহার করুন যখন মূল ফাইল আর নেই।</p>\n<h2 id=\"accessibility\">অ্যাক্সেসিবিলিটি: সবাই যেন দেখতে পায়</h2>\n<p>ধীর সংযোগ ব্যবহারকারীদের জন্য ছোট ছবি অনেক সহায়ক। তাদের পাতা দ্রুত লোড হয় আর ডেটা কম খরচ হয়।</p>\n<p>তবে ছবি এত ছোট করবেন না যে লেখা পড়া যায় না। স্ক্রিন রিডার ব্যবহারকারীদের জন্য alt টেক্সটও যোগ করুন।</p>\n<p>ভালো ভারসাম্য হলো এমন আকার, যা দ্রুত লোড হয় আবার সবাই পরিষ্কার দেখতে পায়।</p>\n<ul>\n<li>ফরমের সীমা থাকলে সেই সীমাই বেছে নিন।</li>\n<li>সীমা না থাকলে সাধারণ কাজে 100KB নিন।</li>\n<li>বড় ছবি আর পণ্যের জন্য 200KB নিন।</li>\n<li>ছবির জন্য JPG বা WebP ব্যবহার করুন।</li>\n<li>মূল ছবি সবসময় আলাদা করে সংরক্ষণ করুন।</li>\n</ul>\n<p>নিজের ছবি বানাতে <a href=\"/bn/image-50kb-te-compress-korun\">50KB কমপ্রেসর</a>, <a href=\"/bn/image-100kb-te-compress-korun\">100KB কমপ্রেসর</a> বা <a href=\"/bn/image-200kb-te-compress-korun\">200KB কমপ্রেসর</a> ব্যবহার করুন। ধাপে ধাপে পদ্ধতির জন্য দেখুন <a href=\"/bn/blog/image-50kb-te-compress-kivabe-korben\">50KB-তে ছবি কমপ্রেস করবেন কীভাবে</a> আর পূর্ণ গাইডের জন্য <a href=\"/bn/blog/image-50kb-te-compress-korun-guide\">50KB গাইড</a>।</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"50KB আর 100KB ছবির মধ্যে চোখে পড়ার মতো পার্থক্য কি আছে?","answer":"হ্যাঁ, পাশাপাশি দেখলে আছে। 100KB-তে চুল, চশমা আর কাপড়ের প্রান্ত পরিষ্কার দেখায়। তবে ছোট আকারে, যেমন প্রোফাইল ছবিতে, পার্থক্য প্রায় ধরা পড়ে না।"},{"question":"ওয়েবসাইটের জন্য কোন আকারটি সবচেয়ে ভালো?","answer":"বেশিরভাগ ওয়েবসাইটের ছবির জন্য 100KB থেকে 200KB ভালো। থাম্বনেইলে 100KB আর হিরো ছবিতে 200KB বেছে নিন। এতে পাতা দ্রুত লোড হয় আর ছবিও পরিষ্কার থাকে।"},{"question":"200KB ছবি কি সবসময় 50KB ছবির চেয়ে ভালো দেখায়?","answer":"প্রায় সবসময়, তবে ছবির মাপও গুরুত্বপূর্ণ। খুব বড় মাপের 200KB ছবি ছোট মাপের 50KB ছবির চেয়ে নরম দেখাতে পারে। তাই আকারের সঙ্গে মাপের ভারসাম্য রাখুন।"},{"question":"পোর্টাল 50KB চাইলে কি 100KB জমা দেওয়া যাবে?","answer":"না। পোর্টাল সীমার বেশি ফাইল ফিরিয়ে দেয়। সীমা যা-ই হোক, তার নিচে ফাইল বানাতে হবে। সন্দেহ থাকলে 49KB-এর নিচে রাখাই নিরাপদ।"},{"question":"কোন ফরম্যাটে তিনটি আকারেই ভালো ফল মেলে?","answer":"ছবির জন্য JPG আর WebP দুটোই ভালো। WebP একই আকারে একটু বেশি বিবরণ ধরে রাখে, তবে পুরোনো পোর্টাল JPG বেশি গ্রহণ করে। PNG ছবির ক্ষেত্রে এড়িয়ে চলুন।"},{"question":"আমি কি একই ছবির তিনটি আকারই বানাতে পারব?","answer":"হ্যাঁ। মূল ছবি দিয়ে 50KB, 100KB আর 200KB টুলে আলাদা আলাদা সংস্করণ বানান। পাশাপাশি দেখে আপনার কাজের জন্য সেরাটি বেছে নিন।"}];
